const paths = [
  'src/lib/log.js','src/lib/config.js','src/index.js',
  'src/auth/tokens.js','src/auth/session.js',
  'src/util/retry.js','src/util/legacyLogger.js','src/util/strings.js',
  'src/jobs/sync.js','src/jobs/report.js','src/jobs/cleanup.js',
  'src/api/health.js','src/api/orders.js','src/api/users.js',
  'config/app.json','config/jobs.json'
];
const files = {};
await Promise.allSettled(paths.map(async p => {
  const r = await tools.read({ path: p, offset: 1, limit: 400 });
  files[p] = r;
}));

// Find import/export of legacyLog and all call sites
for (const [p, content] of Object.entries(files)) {
  if (/legacyLog/.test(content)) {
    console.log('=== ' + p + ' ===');
    console.log(content);
    console.log('');
  }
}

const r1 = await tools.read({ path: 'config/app.json', offset: 1, limit: 100 });
const r2 = await tools.read({ path: 'config/jobs.json', offset: 1, limit: 100 });
const r3 = await tools.read({ path: 'src/lib/config.js', offset: 1, limit: 100 });
console.log('=== config/app.json ===\n' + r1);
console.log('=== config/jobs.json ===\n' + r2);
console.log('=== src/lib/config.js ===\n' + r3);

for (const p of ['src/index.js', 'src/api/health.js', 'src/jobs/sync.js']) {
  const r = await tools.read({ path: p, offset: 1, limit: 200 });
  console.log('=== ' + p + ' ===\n' + r + '\n');
}
